const TASA_IVA = 0.18;

function calcularTotal(monto) {
  return Math.round(monto * (1 + TASA_IVA) * 100) / 100;
}

document.getElementById("calcular").addEventListener("click", () => {
  const monto = Number(document.getElementById("monto").value);
  const salida = document.getElementById("total");
  if (Number.isNaN(monto) || monto <= 0) {
    salida.textContent = "Escribe un monto válido";
    return;
  }
  salida.textContent = calcularTotal(monto).toFixed(2);
});

