import pandas as pd


def resumen(serie):
    """Resumen honesto de una columna numérica."""
    q1, q3 = serie.quantile([0.25, 0.75])
    return {"n": int(serie.count()), "media": round(serie.mean(), 2),
            "mediana": serie.median(), "iqr": q3 - q1}

print(resumen(pd.Series([12, 14, 15, 15, 16, 17, 18, 19, 21, 60])))
